B.akq=new A.f0("g3","Quel moment de ta journ\xe9e t'a rapproch\xe9 d'Allah ?","Which moment of your day brought you closer to Allah?","\ud83c\udf05")
B.ako=new A.f0("g4","Cite 3 choses simples dont tu es reconnaissant(e) aujourd'hui.","Name 3 simple things you are grateful for today.","\ud83e\udd32")
B.akv=new A.f0("g5","Comment Allah t'a-t-Il facilit\xe9 les choses r\xe9cemment ?","How has Allah made things easy for you recently?","\ud83c\udf38")
B.akr=new A.f0("i1","Quel p\xe9ch\xe9 ou mauvaise habitude aimerais-tu d\xe9laisser ?","What sin or bad habit would you like to leave behind?","\ud83e\ude9e")
B.aky=new A.f0("i2","Comment as-tu r\xe9agi face \xe0 une difficult\xe9 aujourd'hui ?","How did you react to a difficulty today?","\ud83d\udcad")
B.akw=new A.f0("i3","As-tu contr\xf4l\xe9 ta langue et \xe9vit\xe9 la m\xe9disance aujourd'hui ?","Did you control your tongue and avoid backbiting today?","\u2696\ufe0f")
B.akh=new A.f0("i4","Si tu devais refaire ta journ\xe9e, que changerais-tu ?","If you could redo your day, what would you change?","\ud83d\udd04")
