B.a2q=new A.c5("\u0625\u0650\u0646\u064e\u0651\u0627 \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0631\u064e\u0627\u062c\u0650\u0639\u064f\u0648\u0646\u064e","Inna lillahi wa inna ilayhi raji'un","Certes, nous appartenons \xe0 Allah et c'est \xe0 Lui que nous retournerons","Verily, we belong to Allah and verily to Him we shall return","Surah Al-Baqarah 2:156")
B.a29=new A.c5("\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0647\u064f \u0648\u064e\u0627\u0631\u0652\u062d\u064e\u0645\u0652\u0647\u064f \u0648\u064e\u0639\u064e\u0627\u0641\u0650\u0647\u0650 \u0648\u064e\u0627\u0639\u0652\u0641\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0623\u064e\u0643\u0652\u0631\u0650\u0645\u0652 \u0646\u064f\u0632\u064f\u0644\u064e\u0647\u064f \u0648\u064e\u0648\u064e\u0633\u0650\u0651\u0639\u0652 \u0645\u064e\u062f\u0652\u062e\u064e\u0644\u064e\u0647\u064f","Allahumma ighfir lahu wa arhamhu wa 'afihi wa a'fu 'anhu wa akrim nuzulahu wa wassi' madkhalaahu","\xd4 Allah, pardonne-lui, sois mis\xe9ricordieux avec lui, accorde-lui l'immunit\xe9, pardonne-lui, honore sa demeure et \xe9largis son entr\xe9e","O Allah, forgive him, be merciful to him, grant him well-being, pardon him, honor his reception, and widen his entrance","Muslim 920")
B.a28=new A.c5("\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0622\u062a\u0650 \u0622\u0644\u064e \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u064e","Allahumma ati al Muhammad al-khayrah","\xd4 Allah, accorde le bien \xe0 la famille de Muhammad","O Allah, grant good to the family of Muhammad","Muslim 915")
