B.al2=new A.ct("R\xe9citez le verset de la gu\xe9rison.","Recite the healing verse.",null,null,"Al-Isra (17:82)",3)
B.akV=new A.ct("R\xe9citez Sourate Al-Ikhlas.","Recite Surah Al-Ikhlas.",null,null,"Al-Ikhlas (112:1-4)",3)
