B.LW=new A.e2("rawatib","Raw\xe2tib (Sunna r\xe9guli\xe8res)","Rawatib (Regular Sunnah)","\ud83d\udcff",15,"12 rak'at : 2 avant Fajr, 4 avant/2 apr\xe8s Dohr, 2 apr\xe8s Maghrib, 2 apr\xe8s Icha","12 rak'ahs: 2 before Fajr, 4 before/2 after Dohr, 2 after Maghrib, 2 after Isha")
B.LR=new A.e2("duha","Pri\xe8re de Duha","Duha Prayer","\ud83c\udf1e",10,"Entre le lever du soleil et le z\xe9nith, 2 \xe0 8 rak'at","Between sunrise and noon, 2 to 8 rak'ahs")
B.LY=new A.e2("witr","Pri\xe8re de Witr","Witr Prayer","\ud83c\udf1b",10,"Apr\xe8s Icha, 1 \xe0 11 rak'at (impair)","After Isha, 1 to 11 rak'ahs (odd number)")
B.LQ=new A.e2("tahajjud","Tahajjud (Qiyam al-Layl)","Tahajjud (Night Prayer)","\ud83c\udf0c",20,"Derni\xe8re partie de la nuit, la meilleure pri\xe8re apr\xe8s les obligatoires","Last part of the night, the best prayer after obligatory ones")
