B.LB=new A.rS("Pri\xe8res sur\xe9rogatoires","Supererogatory Prayers","\u2b50",B.a8o)
B.LV=new A.e2("coran","Lecture du Coran","Quran Recitation","\ud83d\udcd6",15,null,null)
B.LI=new A.e2("dhikr_matin","Adhk\xe2r du matin","Morning Adhkar","\ud83c\udf05",10,null,null)
B.LM=new A.e2("dhikr_soir","Adhk\xe2r du soir","Evening Adhkar","\ud83c\udf07",10,null,null)
B.LP=new A.e2("istighfar","Istighf\xe2r (100x)","Istighfar (100x)","\ud83e\udd32",10,"Le Proph\xe8te \ufdfa demandait pardon \xe0 Allah plus de 100 fois par jour","The Prophet \ufdfa asked forgiveness from Allah more than 100 times daily")
B.LL=new A.e2("salawat","Sal\xe2t 'ala Nabi \ufdfa","Salah upon the Prophet \ufdfa","\ud83d\udc9a",10,"Envoyer les salutations sur le Proph\xe8te \ufdfa","Send blessings upon the Prophet \ufdfa")
B.aa7=s([B.LV,B.LI,B.LM,B.LP,B.LL],t.bC)
B.LE=new A.rS("Adoration & Dhikr","Worship & Dhikr","\ud83d\udc8e",B.aa7)
