B.aBg=new A.rb("Maghrib","\u0627\u0644\u0645\u064e\u063a\u0652\u0631\u0650\u0628","\ud83c\udf06","Coucher du soleil",3,0,2,0,"Se presse pour prier d\xe8s l'entr\xe9e du temps, car son temps est court.")
B.aBe=new A.rb("Isha","\u0627\u0644\u0639\u0650\u0634\u064e\u0627\u0621","\ud83c\udf19","Nuit",4,0,2,3,"Le Witr (1 ou 3 rak'ahs) est fortement recommand\xe9 apr\xe8s Isha. Dernier acte avant de dormir.")
